package com.fooddelivery.order; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*; @RestController @RequestMapping("/api/orders") public class OrderController{final OrderRepository repo; final RestaurantClient client; OrderController(OrderRepository r,RestaurantClient c){repo=r;client=c;} record Item(@NotNull Long menuItemId,@Min(1)int quantity){} record Create(@NotNull Long restaurantId,@NotEmpty List<Item> items,@NotBlank String deliveryAddress,@NotBlank String paymentMethod){} @PostMapping Order create(@Valid @RequestBody Create r,@RequestHeader("X-User-Id")Long userId){BigDecimal total=BigDecimal.ZERO;for(var i:r.items()){var m=client.getItem(i.menuItemId());if(m==null)throw new IllegalArgumentException("Menu item not found");total=total.add(m.price().multiply(BigDecimal.valueOf(i.quantity())));}var o=new Order();o.setCustomerId(userId);o.setRestaurantId(r.restaurantId());o.setTotalAmount(total);o.setDeliveryAddress(r.deliveryAddress());o.setPaymentMethod(r.paymentMethod());o.setPaymentId("DEMO-"+UUID.randomUUID());o.setStatus("PREPARING");o.setOrderTime(LocalDateTime.now());return repo.save(o);} @GetMapping List<Order> mine(@RequestHeader("X-User-Id")Long userId){return repo.findByCustomerIdOrderByOrderTimeDesc(userId);}}